mapper.select:
SELECT , u.real_name AS counselor_name
FROM student s
LEFT JOIN sys_user u ON s.counselor_id = u.id

    s.deleted = 0
    AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
    AND s.name LIKE CONCAT('%', #{name}, '%')
    AND s.gender = #{gender}
    AND s.college = #{college}
    AND s.major = #{major}
    AND s.class_name LIKE CONCAT('%', #{className}, '%')
    AND s.grade = #{grade}
    AND s.dorm_building = #{dormBuilding}
    AND s.political_status = #{politicalStatus}
    AND s.status = #{status}
    AND s.counselor_id = #{counselorId}

ORDER BY s.student_no ASC

SELECT COUNT(1) FROM student

    deleted = 0
    AND status = #{status}
